/* opt_ifmedia.h - a GENERATED file upstream, empty here.
 *
 * FreeBSD's build creates one opt_*.h per kernel config option from the
 * config(8) file; a source file includes the ones it cares about and gets
 * either a #define or an empty file. Genesis has no kernel config step, so
 * the options are simply all off - which is what an empty file means, and is
 * the same answer a GENERIC kernel gives for IFMEDIA_DEBUG.
 *
 * Empty rather than absent: net/if_media.c includes it unconditionally.
 */
